20	const Home: React.FC = () => {
21	  const [newRepo, setNewRepo] = useState('');
22	  const [inputError, setInputError] = useState('');
23	  const [repositories, setRepositories] = useState<Repository[]>(() => {
24	    const storagedRepositories = localStorage.getItem(
25	      '@GihubExplorer:repositories',
26	    );
27	
28	    if (storagedRepositories) {
29	      return JSON.parse(storagedRepositories);
30	    }
31	    return [];
32	  });
33	
34	  async function handleAddRepository(
35	    event: FormEvent<HTMLFormElement>,
36	  ): Promise<void> {
37	    event.preventDefault();
38	
39	    if (!newRepo) {
40	      setInputError('Digite o autor/nome do repositório ');
41	      return;
42	    }
43	    try {
44	      const response = await api.get<Repository>(`repos/${newRepo}`);
45	
46	      const repository = response.data;
47	
48	      setRepositories([...repositories, repository]);
49	
50	      setNewRepo('');
51	
52	      setInputError('');
53	    } catch (error) {
54	      setInputError(
55	        'Erro na busca por esse repositório. Verifique o nome/repositório usados.',
56	      );
57	    }
58	  }
59	
60	  useEffect(() => {
61	    localStorage.setItem(
62	      '@GihubExplorer:repositories',
63	      JSON.stringify(repositories),
64	    );
65	  }, [repositories]);
66	
67	  return (
68	    <>
69	      <img src={logoImage} alt="Github Explorer" />
70	      <Title>Explore repositórios no github.</Title>
71	
72	      <Form hasError={!!inputError} onSubmit={handleAddRepository}>
73	        <input
74	          value={newRepo}
75	          onChange={(e) => setNewRepo(e.target.value)}
76	          placeholder="Digite o nome do repositório"
77	        />
78	        <button type="submit">Pesquisar</button>
79	      </Form>
80	      {inputError && <Error>{inputError}</Error>}
81	
82	      <Repositories>
83	        {repositories.map((repository) => (
84	          <Link key={crypto.randomUUID()} to={`/repositories/${repository.full_name}`}>
85	            <img
86	              src={repository.owner.avatar_url}
87	              alt={repository.owner.login}
88	            />
89	            <div>
90	              <strong>{repository.full_name}</strong>
91	              <p>{repository.description}</p>
92	            </div>
93	            <FiChevronRight size={20} />
94	          </Link>
95	        ))}
96	      </Repositories>
97	
98	      <Footer />
99	    </>
100	  );
101	};
102	
103	export default Home;
