1	import React, { useState, useEffect } from 'react';
2	import { Link, useParams } from 'react-router-dom';
3	import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
4	
5	import api from '../../services/api';
6	
7	import logoImage from '../../assets/logo.svg';
8	import Footer from '../../components/Footer';
9	
10	import { Header, RespositoryInfo, Issues, LoadMoreButton } from './styles';
11	
12	const ISSUES_PER_PAGE = 5;
13	
14	interface Repository {
15	  full_name: string;
16	  description: string;
17	  owner: {
18	    login: string;
19	    avatar_url: string;
20	  };
21	  stargazers_count: number;
22	  forks_count: number;
23	  open_issues_count: number;
24	}
25	interface Issue {
26	  id: number;
27	  title: string;
28	  html_url: string;
29	  user: {
30	    login: string;
31	  };
32	}
33	
34	const Repository: React.FC = () => {
35	  const { '*': repositoryName } = useParams();
36	  const [repository, setRepository] = useState<Repository | null>(null);
37	  const [issues, setIssues] = useState<Issue[]>([]);
38	  const [issuesPage, setIssuesPage] = useState(1);
39	  const [hasMoreIssues, setHasMoreIssues] = useState(true);
40	  const [loadingMoreIssues, setLoadingMoreIssues] = useState(false);
41	
42	  useEffect(() => {
43	    setIssues([]);
44	    setIssuesPage(1);
45	    setHasMoreIssues(true);
46	
47	    api.get(`/repos/${repositoryName}`).then((response) => {
48	      setRepository(response.data);
49	    });
50	    api
51	      .get(`/repos/${repositoryName}/issues`, {
52	        params: {
53	          page: 1,
54	          per_page: ISSUES_PER_PAGE,
55	        },
56	      })
57	      .then((response) => {
58	        setIssues(response.data);
59	        setHasMoreIssues(response.data.length === ISSUES_PER_PAGE);
60	      });
61	  }, [repositoryName]);
62	
63	  async function handleLoadMoreIssues(): Promise<void> {
64	    const nextPage = issuesPage + 1;
65	
66	    setLoadingMoreIssues(true);
67	
68	    try {
69	      const response = await api.get(`/repos/${repositoryName}/issues`, {
70	        params: {
71	          page: nextPage,
72	          per_page: ISSUES_PER_PAGE,
73	        },
74	      });
75	
76	      setIssues([...issues, ...response.data]);
77	      setIssuesPage(nextPage);
78	      setHasMoreIssues(response.data.length === ISSUES_PER_PAGE);
79	    } finally {
80	      setLoadingMoreIssues(false);
81	    }
82	  }
83	
84	  return (
85	    <>
86	      <Header>
87	        <img src={logoImage} alt="Github Explorer" />
88	        <Link to="/">
89	          <FiChevronLeft size={16} color="#3D3D4D" />
90	          <strong>Voltar</strong>
91	        </Link>
92	      </Header>
93	      {repository ? (
94	        <RespositoryInfo>
95	          <header>
96	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
97	            <div>
98	              <strong>{repository.full_name}</strong>
99	              <p>{repository.description}</p>
100	            </div>
101	          </header>
102	          <ul>
103	            <li>
104	              <strong>{repository.stargazers_count}</strong>
105	              <span>Stars</span>
106	            </li>
107	            <li>
108	              <strong>{repository.forks_count}</strong>
109	              <span>Forks</span>
110	            </li>
111	            <li>
112	              <strong>{repository.open_issues_count}</strong>
113	              <span>Issues abertos</span>
114	            </li>
115	          </ul>
116	        </RespositoryInfo>
117	      ) : (
118	        <p>Carregando informações.</p>
119	      )}
120	
121	      <Issues>
122	        {issues.map((issue) => (
123	          <a key={issue.id} href={issue.html_url}>
124	            <div>
125	              <strong>{issue.title}</strong>
126	              <p>{issue.user.login}</p>
127	            </div>
128	            <FiChevronRight size={20} />
129	          </a>
130	        ))}
131	      </Issues>
132	
133	      {hasMoreIssues && (
134	        <LoadMoreButton
135	          type="button"
136	          onClick={handleLoadMoreIssues}
137	          disabled={loadingMoreIssues}
138	        >
139	          {loadingMoreIssues ? 'Carregando...' : 'Carregar mais'}
140	        </LoadMoreButton>
141	      )}
142	
143	      <Footer />
144	    </>
145	  );
146	};
147	
148	export default Repository;
